import numpy as np
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
import csv
import sys

# Optional first argument: label used in the plot titles (e.g. the
# reaction case name such as o18_si30_2n or s36_o18_2n).
label = sys.argv[1] if len(sys.argv) > 1 else "Recoil"

# Read the CSV file generated by Geant4
filename = "stopping_data_nt_RecoilData.csv"
times = []
energies = []

try:
    with open(filename, 'r') as f:
        reader = csv.reader(f)
        for row in reader:
            if not row or row[0].startswith('#'):
                continue
            try:
                times.append(float(row[0]))
                energies.append(float(row[1]))
            except ValueError:
                continue
except FileNotFoundError:
    print(f"Error: {filename} not found.")
    sys.exit(1)

times = np.array(times)
energies = np.array(energies)

bins = 100

# 1. Stopping Time Histogram
counts_t, bin_edges_t = np.histogram(times, bins=bins)
bin_centers_t = (bin_edges_t[:-1] + bin_edges_t[1:]) / 2

ascii_filename_t = "stopping_times_histogram.txt"
with open(ascii_filename_t, 'w') as f:
    f.write("# BinCenter(ps) Counts\n")
    for center, count in zip(bin_centers_t, counts_t):
        f.write(f"{center:.6f} {count}\n")

plt.figure(figsize=(8, 6))
plt.hist(times, bins=bins, color='skyblue', edgecolor='black')
plt.title(f"{label} Recoil Stopping Time Distribution")
plt.xlabel("Stopping Time (ps)")
plt.ylabel("Counts")
plt.grid(axis='y', alpha=0.75)
plt.tight_layout()
plt.savefig("stopping_times_histogram.pdf")
plt.savefig("stopping_times_histogram.png")
plt.close()

# 2. Recoil Energy Histogram
counts_e, bin_edges_e = np.histogram(energies, bins=bins)
bin_centers_e = (bin_edges_e[:-1] + bin_edges_e[1:]) / 2

ascii_filename_e = "recoil_energies_histogram.txt"
with open(ascii_filename_e, 'w') as f:
    f.write("# BinCenter(MeV) Counts\n")
    for center, count in zip(bin_centers_e, counts_e):
        f.write(f"{center:.6f} {count}\n")

plt.figure(figsize=(8, 6))
plt.hist(energies, bins=bins, color='lightcoral', edgecolor='black')
plt.title(f"{label} Recoil Initial Energy Distribution")
plt.xlabel("Initial Energy (MeV)")
plt.ylabel("Counts")
plt.grid(axis='y', alpha=0.75)
plt.tight_layout()
plt.savefig("recoil_energies_histogram.pdf")
plt.savefig("recoil_energies_histogram.png")
plt.close()

# 3. Angular Distribution Plot
try:
    angles = []
    xsecs = []
    with open("../angular_distribution.txt", "r") as f:
        for line in f:
            if line.startswith("#") or not line.strip():
                continue
            parts = line.split()
            if len(parts) >= 2:
                angles.append(float(parts[0]))
                xsecs.append(float(parts[1]))
                
    if angles:
        plt.figure(figsize=(8, 6))
        plt.plot(angles, xsecs, 'b-', linewidth=2)
        plt.title(r"Angular Distribution ($d\sigma/d\Omega$)")
        plt.xlabel(r"Center-of-Mass Angle $\theta_{CM}$ (degrees)")
        plt.ylabel("Cross Section (mb/sr)")
        plt.yscale('log')
        plt.grid(True, which="both", ls="--", alpha=0.5)
        plt.tight_layout()
        plt.savefig("angular_distribution.pdf")
        plt.savefig("angular_distribution.png")
        plt.close()
        print(f"Successfully saved time, energy, and angular distribution histograms (txt, pdf, png)")
    else:
        print(f"Successfully saved time and energy histograms (txt, pdf, png)")
except FileNotFoundError:
    print(f"Successfully saved time and energy histograms (txt, pdf, png)")

# 4. 18O Energy vs Depth Plot
try:
    depths = []
    e_18O = []
    with open("18O_energy_vs_depth.txt", "r") as f:
        for line in f:
            if line.startswith("#") or not line.strip():
                continue
            parts = line.split()
            if len(parts) >= 2:
                depths.append(float(parts[0]))
                e_18O.append(float(parts[1]))
                
    if depths:
        plt.figure(figsize=(8, 6))
        plt.plot(depths, e_18O, 'g-', linewidth=2)
        plt.title("18O Energy vs Depth in Target")
        plt.xlabel(r"Depth ($\mu$m)")
        plt.ylabel("Energy (MeV)")
        plt.grid(True, linestyle="--", alpha=0.7)
        plt.tight_layout()
        plt.savefig("18O_energy_vs_depth.pdf")
        plt.savefig("18O_energy_vs_depth.png")
        plt.close()
        print(f"Successfully saved 18O energy vs depth plot (pdf, png)")
except FileNotFoundError:
    print(f"Note: 18O_energy_vs_depth.txt not found, skipping this plot.")

# 5. Exit Energy Distribution (signed: forward exit +, backward exit -)
try:
    exit_energies = []
    with open(filename, "r") as f:
        reader = csv.reader(f)
        for row in reader:
            if not row or row[0].startswith("#"):
                continue
            try:
                val = float(row[3])
                if val != 0.0:
                    exit_energies.append(val)
            except (ValueError, IndexError):
                continue

    if exit_energies:
        counts_x, bin_edges_x = np.histogram(exit_energies, bins=bins)
        bin_centers_x = (bin_edges_x[:-1] + bin_edges_x[1:]) / 2

        ascii_filename_x = "exit_energy_histogram.txt"
        with open(ascii_filename_x, "w") as f:
            f.write("# BinCenter(MeV) Counts\n")
            for center, count in zip(bin_centers_x, counts_x):
                f.write(f"{center:.6f} {count}\n")

        plt.figure(figsize=(8, 6))
        plt.hist(exit_energies, bins=bins, color="mediumseagreen", edgecolor="black")
        plt.axvline(0.0, color="black", linestyle="--", linewidth=1)
        plt.title(f"{label} Recoil Exit Energy Distribution")
        plt.xlabel("Exit Energy (MeV)  (negative = backward exit)")
        plt.ylabel("Counts")
        plt.grid(axis="y", alpha=0.75)
        plt.tight_layout()
        plt.savefig("exit_energy_histogram.pdf")
        plt.savefig("exit_energy_histogram.png")
        plt.close()
        print(f"Successfully saved exit energy histogram (txt, pdf, png)")
    else:
        print("No transmitted recoils found; exit energy histogram skipped.")
except FileNotFoundError:
    pass
